// UNE PURGE SILENCIEUSE EST LA PLUS DANGEREUSE DES TACHES : le jour ou
// elle efface trop, personne ne s en apercoit, et ce qui est parti ne
// revient que par la sauvegarde. On journalise donc TOUJOURS son bilan,
// meme quand il vaut zero — zero est une information.
const r = $input.first().json || {};
const f = r.fait || {};
const bilan = "Conservation — "
  + (f.paniers || 0) + " panier(s) supprime(s), "
  + (f.commandes || 0) + " commande(s) anonymisee(s), "
  + (f.relances || 0) + " trace(s) de relance retiree(s).";
console.log(bilan);
return [{ json: { bilan, ...r } }];
